import { motion } from 'framer-motion';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import SectionReveal from '../components/SectionReveal';

interface Release {
  version: string;
  date: string;
  title: string;
  highlights: string[];
  changes: { type: 'feat' | 'fix' | 'perf' | 'breaking'; text: string }[];
}

const releases: Release[] = [
  {
    version: '0.5.0',
    date: 'March 7, 2026',
    title: 'Duo Mode & Symphony',
    highlights: [
      'Multi-agent orchestration — run Claude Code and Gemini CLI in parallel',
      'Linear-driven AI development workflows',
      'TOON encoder for 30-60% token savings on MCP responses',
      'Durable file snapshots — your work is never lost',
    ],
    changes: [
      { type: 'feat', text: 'Duo Mode: parallel multi-agent relay engine with dependency-aware scheduling' },
      { type: 'feat', text: 'Smart assignment: complex refactors to Claude, everything else to Gemini (free tier)' },
      { type: 'feat', text: 'Inter-agent relay messages — agents see what the other did between rounds' },
      { type: 'feat', text: 'Claude session resumption across waves (saves ~50% context tokens)' },
      { type: 'feat', text: '3-strike failure handling with automatic agent swapping' },
      { type: 'feat', text: 'Symphony: connect Linear issues directly to AI agent execution' },
      { type: 'feat', text: 'WORKFLOW.md config for Symphony pipelines' },
      { type: 'feat', text: 'TOON (Token-Oriented Object Notation) encoder for MCP tool responses' },
      { type: 'feat', text: 'Durable file snapshots in .aura/snapshots/ — survives without git commits' },
      { type: 'feat', text: 'aura_snapshot MCP tool — AI agents call before editing files' },
      { type: 'feat', text: 'aura_snapshot_list MCP tool — list all recoverable snapshots' },
      { type: 'feat', text: 'Watcher daemon auto-snapshots on every file change' },
      { type: 'feat', text: 'Dev metrics dashboard (React + Vite) — visualize orchestration, checkpoints, reviews' },
      { type: 'fix', text: 'Rewind now searches durable snapshots first, then walks 50 commits of git history' },
      { type: 'fix', text: 'Auto-snapshot before rewind for safety net recovery' },
      { type: 'perf', text: 'Snapshot auto-prune: 50 per file, 500 total max (~2.5MB ceiling)' },
      { type: 'perf', text: 'TOON reduces token count by 30-60% for structured MCP responses' },
    ],
  },
  {
    version: '0.4.0',
    date: 'February 14, 2026',
    title: 'The Governance Update',
    highlights: [
      'High-fidelity semantic PR review engine',
      'Dev Metrics dashboard with real-time AST visualization',
      'Rename-proof logical node identity and diffing',
      '148 features across CLI, MCP, API, and Dashboard',
    ],
    changes: [
      { type: 'feat', text: 'Semantic PR review: detects logical renames, layer violations, cross-branch conflicts' },
      { type: 'feat', text: 'Rename-proof Structural Skeleton Hashing — identity persists regardless of name' },
      { type: 'feat', text: 'Dev Metrics dashboard with checkpoint timeline and logic graph' },
      { type: 'feat', text: 'Policy packs: security, payments, web-app architectural invariant templates' },
      { type: 'feat', text: 'aura prove — mathematically verify behavioral goals via AST path tracing' },
      { type: 'feat', text: 'aura fix — autonomous shadow-branch violation resolution' },
      { type: 'feat', text: 'TypeScript and JavaScript tree-sitter parser support' },
      { type: 'feat', text: 'REST API with 42 endpoints for IDE and CI/CD integration' },
      { type: 'fix', text: 'Non-destructive hook installation — preserves existing git hooks' },
      { type: 'perf', text: 'Handover context compression: 90%+ token reduction for agent relay' },
    ],
  },
  {
    version: '0.3.0',
    date: 'January 18, 2026',
    title: 'The Intelligence Update',
    highlights: [
      'MCP Server with 16 tools for AI agent integration',
      'GSD Orchestrator for wave-based execution',
      'Continuous semantic tracker daemon',
    ],
    changes: [
      { type: 'feat', text: 'MCP Server (JSON-RPC 2.0 over stdio) with 16 semantic tools' },
      { type: 'feat', text: 'GSD Orchestrator: plan, decompose, and execute in atomic waves' },
      { type: 'feat', text: 'Continuous tracker daemon — watches files and persists micro-checkpoints' },
      { type: 'feat', text: 'aura handover — dense XML context blocks for agent relay' },
      { type: 'feat', text: 'Gemini and OpenAI provider support via aura config' },
      { type: 'feat', text: 'Conflict arbitration engine for multi-agent merge conflicts' },
      { type: 'feat', text: 'Ecosystem sync for cross-repo dependency tracking' },
      { type: 'fix', text: 'Git lock detection — daemon pauses during rebase/merge operations' },
    ],
  },
  {
    version: '0.2.0',
    date: 'December 8, 2025',
    title: 'The Foundation',
    highlights: [
      'AST Merkle-Graph with tree-sitter parsing',
      'Surgical rewind for function-level rollback',
      'Intent verification via pre-commit hooks',
    ],
    changes: [
      { type: 'feat', text: 'AST Merkle-Graph: content-addressed semantic nodes for Rust and Python' },
      { type: 'feat', text: 'Surgical rewind: swap individual functions/classes to a previous safe state' },
      { type: 'feat', text: 'Intent verification: pre-commit hook matches AI reasoning to AST changes' },
      { type: 'feat', text: 'Checkpoint system: semantic snapshots stored in git notes' },
      { type: 'feat', text: 'Gatekeeper: deep tree-sitter traversal for forbidden pattern detection' },
      { type: 'feat', text: 'Blast radius projection for architectural deviations' },
      { type: 'feat', text: 'Interactive setup wizard (aura init)' },
    ],
  },
];

const typeBadge = (type: string) => {
  const styles: Record<string, string> = {
    feat: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
    fix: 'bg-amber-500/10 text-amber-400 border-amber-500/20',
    perf: 'bg-blue-500/10 text-blue-400 border-blue-500/20',
    breaking: 'bg-red-500/10 text-red-400 border-red-500/20',
  };
  return styles[type] || styles.feat;
};

const typeLabel: Record<string, string> = {
  feat: 'Feature',
  fix: 'Fix',
  perf: 'Performance',
  breaking: 'Breaking',
};

export default function Changelog() {
  return (
    <div className="min-h-screen bg-[#050505] text-[#F5F5F3] font-sans">
      <Navbar />

      {/* Header */}
      <section className="pt-48 pb-24 px-8 md:px-16 lg:px-24">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, ease: [0.16, 1, 0.3, 1] }}
        >
          <div className="text-[10px] font-mono uppercase tracking-[0.3em] text-white/40 mb-8">
            Engineering Log
          </div>
          <h1 className="text-[48px] md:text-[80px] lg:text-[100px] font-serif leading-[0.9] tracking-tight text-white mb-8">
            Changelog
          </h1>
          <p className="text-[18px] md:text-[22px] text-white/50 leading-[1.6] font-sans max-w-3xl">
            Every release, every feature, every fix. Aura ships fast and breaks nothing.
          </p>
        </motion.div>
      </section>

      {/* Timeline */}
      <section className="px-8 md:px-16 lg:px-24 pb-48">
        <div className="relative">
          {/* Vertical line */}
          <div className="absolute left-[19px] md:left-[23px] top-0 bottom-0 w-[1px] bg-white/10" />

          <div className="flex flex-col gap-24">
            {releases.map((release, idx) => (
              <SectionReveal key={release.version}>
                <div className="relative pl-16 md:pl-20">
                  {/* Dot on timeline */}
                  <div className={`absolute left-0 top-2 w-[10px] h-[10px] md:w-[12px] md:h-[12px] rounded-full border-2 ${idx === 0 ? 'bg-white border-white shadow-[0_0_12px_rgba(255,255,255,0.5)]' : 'bg-[#050505] border-white/30'}`} />

                  {/* Version header */}
                  <div className="flex flex-wrap items-baseline gap-4 mb-2">
                    <h2 className="text-[32px] md:text-[48px] font-serif tracking-tight text-white leading-none">
                      v{release.version}
                    </h2>
                    {idx === 0 && (
                      <span className="text-[10px] font-mono uppercase tracking-[0.2em] bg-white text-black px-3 py-1 font-bold">
                        Latest
                      </span>
                    )}
                  </div>

                  <div className="flex items-center gap-4 mb-8">
                    <span className="text-[13px] font-mono text-white/40">{release.date}</span>
                    <span className="text-[13px] font-mono text-white/20">|</span>
                    <span className="text-[13px] font-mono text-white/60">{release.title}</span>
                  </div>

                  {/* Highlights */}
                  <div className="bg-white/[0.02] border border-white/10 p-6 md:p-8 mb-8">
                    <div className="text-[10px] font-mono uppercase tracking-[0.3em] text-white/40 mb-4">
                      Highlights
                    </div>
                    <ul className="space-y-3">
                      {release.highlights.map((h, i) => (
                        <li key={i} className="flex items-start gap-3">
                          <div className="w-1.5 h-1.5 bg-white/60 mt-2 shrink-0" />
                          <span className="text-[16px] text-white/80 leading-relaxed font-sans">{h}</span>
                        </li>
                      ))}
                    </ul>
                  </div>

                  {/* Detailed changes */}
                  <div className="space-y-2">
                    {release.changes.map((change, i) => (
                      <div key={i} className="flex items-start gap-3 py-1.5">
                        <span className={`text-[10px] font-mono uppercase tracking-wider px-2 py-0.5 border shrink-0 mt-0.5 ${typeBadge(change.type)}`}>
                          {typeLabel[change.type]}
                        </span>
                        <span className="text-[14px] text-white/50 leading-relaxed font-sans">{change.text}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </SectionReveal>
            ))}
          </div>
        </div>
      </section>

      <Footer />
    </div>
  );
}
